INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-mapo', 'mapo', 'published', 2, 0, 25, 25, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-mapo', 'en', 'Mapo Tofu', 'Sichuan classic - silken tofu in a numbing chili-bean sauce.', '', '', '', '[{"name":"400g silken tofu","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"Doubanjiang (broad-bean paste)","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 tsp Sichuan peppercorns","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"150g ground pork","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2 scallions","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Garlic + ginger","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Light soy sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Cornstarch slurry","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true}]', '[{"text":"Cube tofu, blanch 1 min in salted water, drain.","timerSeconds":0},{"text":"Toast Sichuan peppercorns, grind. Set aside.","timerSeconds":0},{"text":"Brown pork in oil. Add ginger, garlic, doubanjiang - cook until red oil separates.","timerSeconds":0},{"text":"Add stock, soy, tofu. Simmer gently 4 min - don''t stir, swirl the pan.","timerSeconds":0},{"text":"Thicken with slurry. Off heat, fold in scallions, dust with peppercorn.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-mapo', 'spicy');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-dandan', 'dandan', 'published', 2, 0, 15, 15, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-dandan', 'en', 'Dan Dan Noodles', 'Chengdu street bowl - sesame, chili oil, vinegar, crisp pork.', '', '', '', '[{"name":"200g wheat noodles","amount":"","unit":"","note":"","aisle":"Noodles","inStore":true},{"name":"2 tbsp Chinese sesame paste","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"2 tbsp chili crisp / chili oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 tbsp Chinkiang black vinegar","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 tbsp light soy sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sui mi ya cai (preserved mustard)","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"100g ground pork","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Scallions","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Whisk sauce: sesame paste, chili oil, vinegar, soy, splash of noodle water.","timerSeconds":0},{"text":"Crisp pork in dry pan with ya cai until dark and fragrant.","timerSeconds":0},{"text":"Boil noodles to bite. Reserve a ladle of water.","timerSeconds":0},{"text":"Pile noodles over sauce. Crown with pork, scallions. Toss at the table.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-dandan', 'spicy');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-dandan', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-garlic-bok-choy', 'garlic-bok-choy', 'published', 2, 0, 10, 10, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-garlic-bok-choy', 'en', 'Garlic Bok Choy & Shiitake', 'Two ingredients, big flavour. Glossy, garlicky, ready in minutes.', '', '', '', '[{"name":"4 heads baby bok choy","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"6 dried shiitake","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Vegetarian oyster (mushroom) sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 tbsp Shaoxing wine","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"4 cloves garlic","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Cornstarch","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Sesame oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true}]', '[{"text":"Soak shiitake 20 min in warm water - keep the soaking liquid.","timerSeconds":0},{"text":"Halve bok choy, blanch 30s, shock in cold water.","timerSeconds":0},{"text":"Sizzle garlic in oil. Add shiitake, splash of wine.","timerSeconds":0},{"text":"Add bok choy, mushroom sauce, a few tbsp soaking liquid.","timerSeconds":0},{"text":"Tighten with cornstarch slurry. Finish with sesame oil.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-garlic-bok-choy', 'vegetarian');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-garlic-bok-choy', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-fried-rice', 'fried-rice', 'published', 2, 0, 12, 12, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-fried-rice', 'en', 'Egg & Scallion Fried Rice', 'Day-old jasmine rice, hot wok, three ingredients done right.', '', '', '', '[{"name":"400g day-old jasmine rice","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"3 eggs","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"4 scallions","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Light soy sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"White pepper","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"Sesame oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Neutral oil","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Beat eggs with a pinch of salt. Slice scallion whites + greens separately.","timerSeconds":0},{"text":"Smoking-hot wok, oil, scramble eggs to soft curds. Lift out.","timerSeconds":0},{"text":"More oil, scallion whites, then rice. Press, toss, repeat - break clumps.","timerSeconds":0},{"text":"Return eggs. Soy down the side of the wok. White pepper.","timerSeconds":0},{"text":"Off heat: scallion greens, sesame oil. Serve immediately.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-fried-rice', 'vegetarian');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-fried-rice', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-crispy-chili-beef', 'crispy-chili-beef', 'published', 2, 0, 30, 30, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-crispy-chili-beef', 'en', 'Crispy Chili Beef Fillet', 'Thin beef strips fried crisp, tossed in a tangy chili-soy glaze.', '', '', '', '[{"name":"400g beef fillet","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2 1/2 tbsp corn starch","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"2 tbsp cooking oil","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tsp sesame seeds","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Marinade: 1 tbsp Lee Kum Kee Premium Oyster Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 2 tbsp Lee Kum Kee Premium Soy Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 2 tbsp Lee Kum Kee Seasoned Rice Vinegar","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tbsp Lee Kum Kee Chiu Chow Chili Oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 5 tbsp water","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 1/2 tbsp sugar","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 1/2 tbsp cooking wine","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Sauce: 1 tbsp corn starch","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true}]', '[{"text":"Cut the beef into thin strips and marinate with oyster sauce for 15-20 minutes.","timerSeconds":0},{"text":"Coat the beef strips in corn starch.","timerSeconds":0},{"text":"Heat oil in a pan over medium heat and fry the beef until browned. Remove and set aside.","timerSeconds":0},{"text":"Add the sauce mixture to the pan and cook for about 5 minutes until slightly thickened.","timerSeconds":0},{"text":"Return the beef to the pan and toss until evenly coated.","timerSeconds":0},{"text":"Sprinkle with sesame seeds before serving.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-crispy-chili-beef', 'spicy');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-golden-wonton-pockets', 'golden-wonton-pockets', 'published', 2, 0, 10, 10, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-golden-wonton-pockets', 'en', 'Golden Wonton Pockets / Gyoza', 'Crisp wonton pockets or gyoza served with bright Lee Kum Kee chili sauces.', '', '', '', '[{"name":"Fried wonton pockets or gyoza","amount":"","unit":"","note":"","aisle":"Freezer","inStore":true},{"name":"Seaweed salad for garnish","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"Lee Kum Kee Chili Sauce with Yuzu Aroma","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Lee Kum Kee Sweet Chili Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Lee Kum Kee Chili Sauce with Kaffir Lime Leaf Aroma","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true}]', '[{"text":"Fry the wontons or gyoza until golden brown.","timerSeconds":0},{"text":"Arrange three pieces on each plate.","timerSeconds":0},{"text":"Place the seaweed salad in the center as garnish.","timerSeconds":0},{"text":"Serve with the sauces.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-golden-wonton-pockets', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-spicy-eggplant-salad', 'spicy-eggplant-salad', 'published', 2, 0, 45, 45, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-spicy-eggplant-salad', 'en', 'Spicy Eggplant Salad', 'Steamed eggplant with garlic, spring onion, sesame and a spicy Ma-La sauce.', '', '', '', '[{"name":"2 eggplants, trimmed and cut into 5 cm strips","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tbsp sesame seeds","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"2 tbsp oil","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"3 garlic cloves, crushed","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 spring onion, finely chopped","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 2 tbsp Lee Kum Kee soy sauce with shallot aroma","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: Lee Kum Kee Red Ma-La Chili Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true}]', '[{"text":"Soak the eggplant in water and vinegar for 30 minutes to keep its purple color. Drain and set aside.","timerSeconds":0},{"text":"Bring water to a boil, place eggplant in a steamer basket and steam for 10 minutes.","timerSeconds":0},{"text":"Put garlic, spring onion and sesame seeds in a bowl. Heat about 2 tbsp oil and pour it over the mixture.","timerSeconds":0},{"text":"Stir in the remaining sauce ingredients.","timerSeconds":0},{"text":"Arrange the cooled eggplant on a plate, pour the sauce over it and serve.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-spicy-eggplant-salad', 'spicy');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-spicy-eggplant-salad', 'vegetarian');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-garlic-prawns-glass-noodles', 'garlic-prawns-glass-noodles', 'published', 2, 0, 20, 20, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-garlic-prawns-glass-noodles', 'en', 'Garlic Prawns with Glass Noodles', 'Tiger prawns steamed over glass noodles with a glossy garlic soy-oyster sauce.', '', '', '', '[{"name":"12-15 tiger prawns with shell","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 nest vermicelli glass noodles","amount":"","unit":"","note":"","aisle":"Noodles","inStore":true},{"name":"2 tbsp vegetable oil","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2 garlic cloves, finely chopped","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 spring onion, finely chopped","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 1/2 tbsp Lee Kum Kee Premium Oyster Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1/2 tbsp Lee Kum Kee Premium Light Soy Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tsp Lee Kum Kee Pure Sesame Oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true}]', '[{"text":"Soak the glass noodles in warm water until soft. Drain and place on a plate.","timerSeconds":0},{"text":"Rinse the prawns and pat dry. Peel them, leaving the tail section on.","timerSeconds":0},{"text":"Gently fry the garlic in sesame oil until lightly golden. Add oyster sauce and light soy sauce.","timerSeconds":0},{"text":"Place the prawns on the glass noodles and pour the garlic sauce over them.","timerSeconds":0},{"text":"Steam over boiling water for 5-7 minutes.","timerSeconds":0},{"text":"Sprinkle with spring onion. Heat oil and pour it over the prawns before serving.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-garlic-prawns-glass-noodles', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-honey-lime-soy-chicken', 'honey-lime-soy-chicken', 'published', 3, 0, 45, 45, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-honey-lime-soy-chicken', 'en', 'Honey-Lime Soy Chicken', 'Chicken thigh fillets baked with honey, lime, garlic and light soy sauce.', '', '', '', '[{"name":"500g chicken thigh fillets","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 handful coriander or spring onions, chopped","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 2 tbsp Lee Kum Kee Premium Light Soy Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Marinade: 2 tbsp honey","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 2 tbsp fresh lime juice","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 2 garlic cloves, crushed","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 1/2 tsp ground black pepper","amount":"","unit":"","note":"","aisle":"Spices","inStore":true}]', '[{"text":"Marinate the chicken for at least 2 hours.","timerSeconds":0},{"text":"Preheat oven to 180 degrees C.","timerSeconds":0},{"text":"Place the chicken on a baking tray and reserve the marinade.","timerSeconds":0},{"text":"Bake for 25 minutes. Halfway through, brush the chicken with the reserved marinade.","timerSeconds":0},{"text":"Garnish with coriander or spring onions and serve.","timerSeconds":0}]', '{}');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-lucky-cabbage-parcels', 'lucky-cabbage-parcels', 'published', 3, 0, 35, 35, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-lucky-cabbage-parcels', 'en', 'Lucky Cabbage Parcels', 'Soft Chinese cabbage leaves wrapped around pork, carrot and water chestnut filling.', '', '', '', '[{"name":"300g minced pork","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Chinese cabbage leaves","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"40g water chestnuts, finely diced","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1 carrot, finely diced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 1 tbsp Lee Kum Kee Premium Oyster Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Marinade: 1 tbsp Lee Kum Kee Premium Light Soy Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Marinade: 1 tbsp Lee Kum Kee Pure Sesame Oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Marinade: 1 tsp sugar","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 1 tsp corn starch","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Marinade: 1 tsp water","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 1 tsp ground white pepper","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"Sauce: 2 tbsp Lee Kum Kee Premium Oyster Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tsp Lee Kum Kee Pure Sesame Oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 2 tbsp water","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 1 tsp corn starch","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true}]', '[{"text":"Boil the Chinese cabbage leaves in hot water until soft. Drain and set aside.","timerSeconds":0},{"text":"Mix minced pork, diced carrot, water chestnuts and all marinade ingredients thoroughly.","timerSeconds":0},{"text":"Fill the soft cabbage leaves with the pork mixture.","timerSeconds":0},{"text":"Steam over high heat for 10 minutes until fully cooked.","timerSeconds":0},{"text":"Cook the sauce mixture over low heat until thickened.","timerSeconds":0},{"text":"Pour the sauce over the parcels and serve.","timerSeconds":0}]', '{}');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-steamed-fish-slices', 'steamed-fish-slices', 'published', 2, 0, 30, 30, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-steamed-fish-slices', 'en', 'Steamed Fish Slices', 'Sea bass slices steamed over tofu with black bean garlic oyster sauce.', '', '', '', '[{"name":"250g sea bass fillet","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"10 soft tofu cubes","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"1/2 pinch salt","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tsp Lee Kum Kee Premium Mushroom Seasoning Powder","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1 pinch ground white pepper","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"1 tsp water","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 bunch pak choi, thinly sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2 spring onions, finely chopped","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 1 tbsp Lee Kum Kee Black Bean Garlic Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tbsp Lee Kum Kee Premium Oyster Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tsp sugar","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 1 tsp corn starch","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Sauce: 1 tbsp water","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Cut the sea bass fillet into 5 thin slices. Marinate for 15 minutes with mushroom seasoning powder, white pepper and water.","timerSeconds":0},{"text":"Cut the soft tofu into 10 cubes.","timerSeconds":0},{"text":"Spread the tofu cubes on a serving plate and place the marinated fish slices on top.","timerSeconds":0},{"text":"Steam over high heat for 8 minutes.","timerSeconds":0},{"text":"Meanwhile, mix all sauce ingredients in a small pot and cook over low heat until slightly thickened.","timerSeconds":0},{"text":"When the fish is cooked, pour the sauce over the fish and tofu.","timerSeconds":0},{"text":"Garnish with chili and spring onions and serve immediately.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-steamed-fish-slices', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-harvest-vegetable-pan', 'harvest-vegetable-pan', 'published', 2, 0, 15, 15, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-harvest-vegetable-pan', 'en', 'Harvest Vegetable Pan', 'Sweet corn, carrot, peas and pine nuts with mushroom seasoning and sesame oil.', '', '', '', '[{"name":"1 small can sweet corn, drained","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Carrots, diced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Frozen peas","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Pine nuts","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tsp cooking oil","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Seasoning: 1 tbsp Lee Kum Kee Premium Mushroom Seasoning Powder","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Seasoning: 1 tsp Lee Kum Kee Pure Sesame Oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Salt, optional","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Toast the pine nuts in a dry pan over low heat until golden and fragrant. Remove and set aside.","timerSeconds":0},{"text":"Heat 1 tsp oil in the same pan. Add diced carrots and fry for 2-3 minutes until slightly soft.","timerSeconds":0},{"text":"Add peas and corn. Stir-fry for another 2-3 minutes.","timerSeconds":0},{"text":"Add 2-3 tbsp water, cover the pan and steam briefly until the carrots are soft.","timerSeconds":0},{"text":"Stir in the mushroom seasoning powder and season with salt if needed.","timerSeconds":0},{"text":"Drizzle with sesame oil and mix well.","timerSeconds":0},{"text":"Add the toasted pine nuts before serving.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-harvest-vegetable-pan', 'vegetarian');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-harvest-vegetable-pan', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-tofu-salad', 'tofu-salad', 'published', 2, 0, 10, 10, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-tofu-salad', 'en', 'Tofu Salad', 'Firm tofu, cucumber, lettuce and tomatoes with roasted sesame dressing.', '', '', '', '[{"name":"200g firm tofu, drained and diced","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"1 cucumber, sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"4-6 lettuce leaves, torn into bite-sized pieces","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"200g cherry tomatoes, halved","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Dressing: 3 tbsp Lee Kum Kee Roasted Sesame Dressing","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true}]', '[{"text":"Prepare the tofu according to the package instructions.","timerSeconds":0},{"text":"Mix all ingredients and the dressing in a large salad bowl.","timerSeconds":0},{"text":"Toss well and serve.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-tofu-salad', 'vegetarian');
