INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-vietnamese-prawn-mango-rolls', 'vietnamese-prawn-mango-rolls', 'published', 4, 0, 25, 25, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-vietnamese-prawn-mango-rolls', 'en', 'Vietnamese Prawn-Mango Summer Rolls', 'Fresh rice paper rolls with prawns, mango, cucumber, lettuce and mint.', '', '', '', '[{"name":"8 pieces Vietnamese rice paper","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"16 cooked king prawns","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"100g ripe mango, sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"80g cucumber, julienned","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"80g mild lettuce","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"16 mint leaves","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 red chili, julienned, optional","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Dip: 2 tbsp Lee Kum Kee Seasoned Rice Vinegar","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Dip: 1 tbsp Lee Kum Kee Premium Soy Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Dip: 1 tsp Lee Kum Kee Pure Sesame Oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Dip: 1 tsp honey","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Prepare a shallow bowl with water and a clean kitchen towel.","timerSeconds":0},{"text":"Soak one rice paper sheet at a time in cold water for 20-30 seconds until soft. Place it on the towel to drain.","timerSeconds":0},{"text":"Place the filling ingredients at one end of the rice paper. Roll tightly, fold in the sides and finish rolling.","timerSeconds":0},{"text":"Cut the summer rolls in half and serve with the dip sauce.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-vietnamese-prawn-mango-rolls', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-poke-bowl', 'poke-bowl', 'published', 2, 0, 20, 20, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-poke-bowl', 'en', 'Poke Bowl', 'Rice, salmon, vegetables, kimchi and a chili-garlic oyster sauce.', '', '', '', '[{"name":"250g cooked rice","amount":"","unit":"","note":"","aisle":"Rice","inStore":true},{"name":"200g raw salmon, sashimi quality, diced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2 tbsp edamame, blanched","amount":"","unit":"","note":"","aisle":"Freezer","inStore":true},{"name":"1 small cucumber, cut into sticks","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1/2 carrot, grated","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1/2 avocado, diced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2 tbsp kimchi, optional","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"Sauce: 1 spring onion, finely sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 1 tbsp Lee Kum Kee Premium Oyster Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tbsp Lee Kum Kee Chilli Garlic Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tsp Lee Kum Kee Dumpling Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tsp honey","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Garnish: 1 tsp toasted sesame seeds","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Garnish: 2 pieces toasted nori","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true}]', '[{"text":"Cook the rice according to the package instructions.","timerSeconds":0},{"text":"Mix the sauce ingredients in a bowl and add the salmon cubes.","timerSeconds":0},{"text":"Put the rice in a large bowl. Arrange the vegetables around the rice, leaving space in the middle.","timerSeconds":0},{"text":"Place the salmon in the center.","timerSeconds":0},{"text":"Sprinkle with sesame seeds and place the nori on the side. Serve.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-poke-bowl', 'quick');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-poke-bowl', 'spicy');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-noodle-salad-chicken', 'noodle-salad-chicken', 'published', 2, 0, 15, 15, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-noodle-salad-chicken', 'en', 'Noodle Salad with Chicken', 'Egg noodles topped with chicken, vegetables and Lee Kum Kee peanut sauce.', '', '', '', '[{"name":"300g cooked egg noodles","amount":"","unit":"","note":"","aisle":"Noodles","inStore":true},{"name":"1 medium carrot, julienned","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"100g bean sprouts, blanched","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 cucumber, sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"400g cooked chicken, shredded","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"4 tbsp Lee Kum Kee Peanut Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true}]', '[{"text":"Divide the noodles between two bowls.","timerSeconds":0},{"text":"Arrange the remaining ingredients on top of the noodles.","timerSeconds":0},{"text":"Toss with peanut sauce.","timerSeconds":0},{"text":"Serve and enjoy.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-noodle-salad-chicken', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-wasabi-prawns-asparagus', 'wasabi-prawns-asparagus', 'published', 2, 0, 15, 15, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-wasabi-prawns-asparagus', 'en', 'Fried Wasabi King Prawns with Green Asparagus', 'King prawns and asparagus finished with sesame dressing with wasabi aroma.', '', '', '', '[{"name":"180g raw peeled king prawns","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"110g thin green asparagus, cut into 4 cm pieces","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tbsp light olive oil","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tbsp Lee Kum Kee Sesame Dressing with Wasabi Aroma","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Garnish: lime wedges","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Devein the prawns and optionally butterfly them. Blanch the asparagus and drain.","timerSeconds":0},{"text":"Blanch asparagus pieces for about 2 minutes in simmering water, then drain.","timerSeconds":0},{"text":"Heat oil in a pan. Add prawns and cook until pink.","timerSeconds":0},{"text":"Add asparagus and toss everything together.","timerSeconds":0},{"text":"Remove from heat and mix with the sesame-wasabi dressing.","timerSeconds":0},{"text":"Garnish with lime wedges and serve.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-wasabi-prawns-asparagus', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-cold-mixed-vegetables', 'cold-mixed-vegetables', 'published', 2, 0, 15, 15, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-cold-mixed-vegetables', 'en', 'Cold Mixed Vegetables', 'Lotus root, onion, pepper and carrot in a light mushroom-soy dressing.', '', '', '', '[{"name":"200g lotus root, thinly sliced","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"20g red onion, thinly sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"20g yellow or red bell pepper, sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"20g carrot, julienned","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Sauce: 1 tbsp Lee Kum Kee Premium Mushroom Seasoning Powder","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Sauce: 2 tsp Lee Kum Kee Premium Light Soy Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Sauce: 1 tsp lemon juice","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Bring water to a boil and blanch the lotus root until almost cooked.","timerSeconds":0},{"text":"Cool in cold water and drain.","timerSeconds":0},{"text":"Mix the sauce with onion, bell pepper, carrot and lotus root.","timerSeconds":0},{"text":"Serve cold.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-cold-mixed-vegetables', 'vegetarian');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-cold-mixed-vegetables', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-tom-yum-chicken-spaghetti', 'tom-yum-chicken-spaghetti', 'published', 3, 0, 25, 25, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-tom-yum-chicken-spaghetti', 'en', 'Chicken Basil Spaghetti with Tom Yum Sauce', 'Spaghetti with chicken, basil and a coconut Tom Yum sauce.', '', '', '', '[{"name":"350g chicken breast, cut into small pieces","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"400g spaghetti","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 onion, grated","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"15 fresh basil leaves, torn","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 pinch ground black pepper","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"1 tbsp oil","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 1 tbsp Lee Kum Kee Tom Yum Bouillon","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Sauce: 2 tbsp Lee Kum Kee Tom Yum Bouillon","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Sauce: 2 tbsp coconut milk or water","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Sauce: 4 tbsp spaghetti cooking water","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Marinate the chicken for 10 minutes.","timerSeconds":0},{"text":"Cook the spaghetti 1 minute less than the package instructions. Drain and set aside.","timerSeconds":0},{"text":"Heat oil in a pan over medium heat. Saute the onion, then add chicken and stir-fry for about 3 minutes until almost cooked.","timerSeconds":0},{"text":"Add sauce mixture and spaghetti. Toss well.","timerSeconds":0},{"text":"Sprinkle with basil and black pepper and serve.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-tom-yum-chicken-spaghetti', 'spicy');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-mushroom-asparagus-risotto', 'mushroom-asparagus-risotto', 'published', 3, 0, 35, 35, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-mushroom-asparagus-risotto', 'en', 'Mushroom and Asparagus Risotto', 'Creamy risotto with mushrooms, asparagus and umami mushroom bouillon.', '', '', '', '[{"name":"300g risotto rice","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"200g mushrooms, sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"120g asparagus, peeled and halved","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 onion, chopped","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"50g vegan parmesan, grated","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tbsp mixed herbs","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"2 tbsp olive oil","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 pinch freshly ground black pepper","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"Broth: 1 packet Lee Kum Kee Umami Mushroom Bouillon","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Broth: 1.2 liters hot water","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Mix the bouillon with hot water and keep warm.","timerSeconds":0},{"text":"Blanch asparagus, cool in cold water, drain and set aside.","timerSeconds":0},{"text":"Heat oil in a pan over medium heat. Saute onion, mushrooms and rice.","timerSeconds":0},{"text":"Gradually add the broth. Each time the rice absorbs the liquid, add more broth and stir.","timerSeconds":0},{"text":"Continue until the rice is al dente.","timerSeconds":0},{"text":"Add asparagus and parmesan. Stir well.","timerSeconds":0},{"text":"Serve with black pepper.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-mushroom-asparagus-risotto', 'vegetarian');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-seafood-rice-soup', 'seafood-rice-soup', 'published', 2, 0, 25, 25, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-seafood-rice-soup', 'en', 'Rice Soup with Assorted Seafood', 'Comforting rice soup with mixed seafood and Lee Kum Kee seafood bouillon.', '', '', '', '[{"name":"250g mixed seafood, for example prawns, clams, squid or scallops","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2 bowls cooked rice","amount":"","unit":"","note":"","aisle":"Rice","inStore":true},{"name":"1 packet Lee Kum Kee Seafood Bouillon","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1 liter hot water","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Chopped spring onion and coriander, optional","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Optional dip: 2 tbsp Lee Kum Kee Premium Soy Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Optional dip: 1 tsp Lee Kum Kee Seasoned Rice Vinegar","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Optional dip: 1 tsp Lee Kum Kee Chiu Chow Chili Oil","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true}]', '[{"text":"Add the bouillon to the hot water, mix well and bring to a boil.","timerSeconds":0},{"text":"Add cooked rice and cook for at least 15 minutes until the rice has swollen.","timerSeconds":0},{"text":"Add the seafood and cook until done.","timerSeconds":0},{"text":"Add spring onion and coriander.","timerSeconds":0},{"text":"Serve with the optional dip sauce if desired.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-seafood-rice-soup', 'quick');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-spicy-fish-soup', 'spicy-fish-soup', 'published', 3, 0, 25, 25, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-spicy-fish-soup', 'en', 'Spicy Fish Soup with Fish Fillet', 'Sichuan-style fish fillet soup with tomatoes, enoki and spicy bouillon.', '', '', '', '[{"name":"400g sea bass or cod fillet","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"100g enoki mushrooms","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"3 tomatoes","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Coriander for garnish, optional","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 1 egg","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 2 tbsp corn starch","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Marinade: 1 tsp salt","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 1 tsp cooking wine","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Marinade: 1/2 tsp ground white pepper","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"Bouillon: 1 packet Lee Kum Kee Spicy Bouillon Sichuan Style","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Bouillon: 1 tbsp Lee Kum Kee Premium Oyster Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Bouillon: 1 tsp sugar","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Bouillon: 1.2 liters hot water","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Clean the fish fillets, pat dry and cut into thick slices. Marinate for 15 minutes.","timerSeconds":0},{"text":"Bring the bouillon mixture to a boil. Add enoki mushrooms and tomatoes and cook for 2 minutes.","timerSeconds":0},{"text":"Add the marinated fish and cook for about 3 minutes or until done.","timerSeconds":0},{"text":"Serve immediately.","timerSeconds":0}]', '{}');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('homepage-spicy-fish-soup', 'spicy');
INSERT INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES ('homepage-satay-rice-noodle-soup', 'satay-rice-noodle-soup', 'published', 3, 0, 25, 25, 'easy', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES ('homepage-satay-rice-noodle-soup', 'en', 'Satay Soup with Rice Noodles, Chicken and Vegetables', 'Rice noodles in satay bouillon with chicken, carrot, onion and baby corn.', '', '', '', '[{"name":"400g cooked rice noodles or 200g raw rice noodles","amount":"","unit":"","note":"","aisle":"Noodles","inStore":true},{"name":"200g chicken breast, cut into pieces","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"60g carrot, grated","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"40g onion, grated","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"60g baby corn, halved","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1 tbsp oil","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"Marinade: 1 tbsp Lee Kum Kee Premium Oyster Sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Bouillon: 1 packet Lee Kum Kee Satay Bouillon","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"Bouillon: 1.2 liters hot water","amount":"","unit":"","note":"","aisle":"","inStore":false}]', '[{"text":"Marinate the chicken for 10 minutes.","timerSeconds":0},{"text":"Heat oil in a pan over medium heat and fry the chicken until cooked.","timerSeconds":0},{"text":"Add the vegetables and stir-fry for 2 minutes.","timerSeconds":0},{"text":"Bring 1.2 liters water and the bouillon to a boil. Add rice noodles and cook for 2 minutes or according to the package instructions.","timerSeconds":0},{"text":"Divide the noodles into bowls, add chicken and vegetables, pour the boiling soup over them and serve.","timerSeconds":0}]', '{}');
